package com.chatsystem.user.controller.group;
import com.chatsystem.shared.model.*;import com.chatsystem.shared.model.status.GroupRole;import com.chatsystem.shared.service.GroupService;import com.chatsystem.shared.session.UserSession;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.GroupMemberCell;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.HBox;
public final class GroupDetailsController{private final GroupService groups;private final UserSession session;private final UserNavigator nav;private long id;private Runnable pending;@FXML private TextField nameField;@FXML private TextArea descriptionField;@FXML private ListView<ConversationMember> memberList;@FXML private ChoiceBox<GroupRole> roleChoice;@FXML private Button changeRoleButton,removeMemberButton;@FXML private Label groupFeedbackLabel;@FXML private HBox groupConfirmationBar;public GroupDetailsController(GroupService g,UserSession s,UserNavigator n){groups=g;session=s;nav=n;}@FXML private void initialize(){roleChoice.getItems().setAll(GroupRole.values());memberList.setCellFactory(x->new GroupMemberCell());}@FXML private void save(){var r=groups.updateGroup(id,nameField.getText(),descriptionField.getText());feedback(r.isSuccess()?"Group updated":r.errors().get(0).message());}@FXML private void changeRole(){var m=memberList.getSelectionModel().getSelectedItem();if(m==null||roleChoice.getValue()==null){feedback("Choose a member and role");return;}var r=groups.changeRole(id,m.getUserId(),roleChoice.getValue());feedback(r.isSuccess()?"Role updated":r.errors().get(0).message());}@FXML private void remove(){var m=memberList.getSelectionModel().getSelectedItem();if(m==null){feedback("Choose a member");return;}confirm(()->{var r=groups.removeMember(id,m.getUserId());feedback(r.isSuccess()?"Member removed":r.errors().get(0).message());});}@FXML private void leave(){confirm(()->{var r=groups.leaveGroup(id);if(r.isSuccess())nav.navigate(ViewRequest.of(UserRoute.GROUP_MANAGEMENT));else feedback(r.errors().get(0).message());});}@FXML private void confirmAction(){if(pending!=null)pending.run();cancelAction();}@FXML private void cancelAction(){pending=null;groupConfirmationBar.setManaged(false);groupConfirmationBar.setVisible(false);}@FXML private void invite(){nav.showDialog("/fxml/dialogs/invite-members.fxml","Invite member",c->((InviteMembersDialogController)c).present(id));}@FXML private void back(){nav.navigate(ViewRequest.of(UserRoute.GROUP_MANAGEMENT));}public void present(long groupId){id=groupId;Conversation g=groups.getGroups().stream().filter(x->x.getId()==id).findFirst().orElse(null);if(g==null){feedback("Group is unavailable");return;}nameField.setText(g.getName());descriptionField.setText(g.getDescription());memberList.setItems(groups.getMembers(id));boolean admin=groups.getMembers(id).stream().anyMatch(m->m.getUserId()==session.getCurrentUser().getId()&&m.getRole()==GroupRole.ADMIN);roleChoice.setDisable(!admin);changeRoleButton.setDisable(!admin);removeMemberButton.setDisable(!admin);}private void confirm(Runnable r){pending=r;groupConfirmationBar.setManaged(true);groupConfirmationBar.setVisible(true);}private void feedback(String t){groupFeedbackLabel.setText(t);}}
